using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using EasyEcs.Core.Components;

namespace EasyEcs.Core;

// Shared, non-arity-specific core of component storage and structural changes.
// The public T1..T9 overloads (AddComponents, RemoveComponents, ...) are generated by EasyEcs.Generator.
public partial class World
{
    /// <summary>
    /// Register <typeparamref name="T"/>'s bit and make sure this world has a column for it.
    /// Must be called inside _structuralLock.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private ushort PrepareColumn<T>() where T : struct, IComponent
    {
        ushort bit = ComponentType<T>.Bit;
        var columns = Components;
        if (columns == null || bit >= columns.Length || columns[bit] == null || columns[bit].Length < Entities.Length)
            EnsureComponentArray<T>(bit);
        return bit;
    }

    /// <summary>Typed column of component <typeparamref name="T"/>; the column must exist.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal T[] Column<T>(ushort bit) where T : struct, IComponent =>
        Unsafe.As<T[]>(Unsafe.Add(ref MemoryMarshal.GetArrayDataReference(Components), bit));

    /// <summary>Ref to <typeparamref name="T"/> of entity <paramref name="id"/> without bounds checks.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal ref T ColumnRef<T>(ushort bit, int id) where T : struct, IComponent =>
        ref Unsafe.Add(ref MemoryMarshal.GetArrayDataReference(Column<T>(bit)), id);

    /// <summary>
    /// Set <paramref name="bits"/> on the entity's tag and move it to the resulting archetype in one transition.
    /// Single-bit changes follow the cached transition edge (no Tag hashing). Must be called inside _structuralLock.
    /// </summary>
    private void AddBits(int id, ReadOnlySpan<ushort> bits)
    {
        ref var tag = ref Entities[id].Tag;
        if (bits.Length == 1)
        {
            int bit = bits[0];
            if (tag.HasBit(bit)) return;
            tag.SetBit(bit);
            MoveToArchetype(id, ArchetypeAfterAdd(Meta[id].Archetype, bit, in tag));
            return;
        }

        bool changed = false;
        for (int i = 0; i < bits.Length; i++)
        {
            if (tag.HasBit(bits[i])) continue;
            tag.SetBit(bits[i]);
            changed = true;
        }

        if (changed)
            MoveToArchetype(id, GetOrCreateArchetype(in tag));
    }

    /// <summary>
    /// Clear <paramref name="bits"/> from the entity's tag, move it to the resulting archetype in one transition and
    /// reset the removed components' data. Must be called inside _structuralLock.
    /// </summary>
    private void RemoveBits(int id, ReadOnlySpan<ushort> bits)
    {
        ref var tag = ref Entities[id].Tag;
        int removed = 0, lastBit = 0;
        for (int i = 0; i < bits.Length; i++)
        {
            int bit = bits[i];
            if (!tag.HasBit(bit)) continue;
            tag.ClearBit(bit);
            Array.Clear(Components[bit], id, 1); // release managed references held by the component
            lastBit = bit;
            removed++;
        }

        if (removed == 1)
            MoveToArchetype(id, ArchetypeAfterRemove(Meta[id].Archetype, lastBit, in tag));
        else if (removed > 1)
            MoveToArchetype(id, GetOrCreateArchetype(in tag));
    }

    /// <summary>
    /// Create or grow the column of <typeparamref name="T"/> to the entity capacity. Must be called inside
    /// _structuralLock. Bumps StorageVersion so in-flight ForEach passes refresh cached columns.
    /// </summary>
    [MethodImpl(MethodImplOptions.NoInlining)]
    private void EnsureComponentArray<T>(ushort bit) where T : struct, IComponent
    {
        if (Components == null || bit >= Components.Length)
            Array.Resize(ref Components, Math.Max((Components?.Length ?? 0) * 2, bit + 1));

        var column = (T[])Components[bit];
        if (column == null)
            Components[bit] = new T[Entities.Length];
        else if (column.Length < Entities.Length)
        {
            Array.Resize(ref column, Entities.Length);
            Components[bit] = column;
        }

        StorageVersion++;
    }

}
